INSERT INTO facets (`slug`, `page_type`, `parent_slug`, `h1`, `title`, `intro_copy`, `meta_title`, `meta_description`, `rules`, `canonical_path`, `indexable`, `position`) VALUES
  ('toyota', 'make', NULL, 'Toyota cars for sale in Port Harcourt', 'Toyota for sale in Port Harcourt', 'Toyota is the default PH buy for a reason: parts on every street, mechanics who know the platform, and resale value that holds. Every car here is graded honestly — you can see which ones our inspectors have physically checked.', 'Toyota Cars for Sale in Port Harcourt — Verified Stock | HonestCars', 'Browse verified Toyota cars for sale in Port Harcourt — Camry, Corolla, RAV4, Highlander, Hilux. Honest prices, inspection grades, no dealer games.', '{"make":"Toyota"}', '/cars/toyota', 1, 10),
  ('toyota/camry', 'model', 'toyota', 'Toyota Camry for sale in Port Harcourt', 'Toyota Camry in Port Harcourt', 'The Camry is the safest first buy in Port Harcourt: comfortable, cheap to service, and easy to resell. Below is live Camry stock with mileage, documents status and our verification grade on each one.', 'Toyota Camry for Sale in Port Harcourt — Prices & Verified Stock | HonestCars', 'Live Toyota Camry listings in Port Harcourt with honest prices, verified mileage and inspection grades. Compare 2010–2018 Camry stock before you travel.', '{"make":"Toyota","model":"Camry"}', '/cars/toyota/camry', 1, 11),
  ('toyota/corolla', 'model', 'toyota', 'Toyota Corolla for sale in Port Harcourt', 'Toyota Corolla in Port Harcourt', 'Corolla money is safe money in PH. Fuel is light, parts are cheap, and a well-kept example will not embarrass you. We list the mileage as it is — verified where an inspector has seen the odometer.', 'Toyota Corolla for Sale in Port Harcourt — Verified Corolla Stock | HonestCars', 'Toyota Corolla listings in Port Harcourt with verified mileage, document status and honest condition notes. Prices from the live PH market.', '{"make":"Toyota","model":"Corolla"}', '/cars/toyota/corolla', 1, 12),
  ('honda', 'make', NULL, 'Honda cars for sale in Port Harcourt', 'Honda for sale in Port Harcourt', 'Hondas hold their value in Port Harcourt and the Accord and CR-V are the two we see most. Check the grade on each listing — Certified means we scanned it ourselves and wrote down what we found.', 'Honda Cars for Sale in Port Harcourt — Verified Accord & CR-V | HonestCars', 'Browse Honda cars for sale in Port Harcourt — Accord, CR-V, Civic, Pilot. Verified grades, real mileage, honest condition notes.', '{"make":"Honda"}', '/cars/honda', 1, 20),
  ('honda/accord', 'model', 'honda', 'Honda Accord for sale in Port Harcourt', 'Honda Accord in Port Harcourt', 'The Accord gives you Camry comfort with a bit more presence. Service costs are close, parts are available around Ikwerre Road and Rumuokoro. Ask us for the history on any car below.', 'Honda Accord for Sale in Port Harcourt — Prices & Grades | HonestCars', 'Honda Accord listings in Port Harcourt with honest prices, mileage and verification grades. Compare before you call.', '{"make":"Honda","model":"Accord"}', '/cars/honda/accord', 1, 21),
  ('lexus', 'make', NULL, 'Lexus cars for sale in Port Harcourt', 'Lexus for sale in Port Harcourt', 'Lexus money buys you Toyota reliability with a quieter cabin. Fuel and suspension parts cost more than a Camry, so we flag anything the inspector found before you commit.', 'Lexus Cars for Sale in Port Harcourt — RX, ES & GX Stock | HonestCars', 'Verified Lexus listings in Port Harcourt — RX 350, ES 350, GX 460. Real prices, inspection grades and document status on every car.', '{"make":"Lexus"}', '/cars/lexus', 1, 30),
  ('suv-under-15m', 'body_budget', NULL, 'SUVs under ₦15m in Port Harcourt', 'SUVs under ₦15m in Port Harcourt', 'Family height and Abuja-road confidence do not have to start at ₦20m. Everything here is under ₦15,000,000 and every price is the price — what you see is what the dealer is asking.', 'SUVs Under ₦15m in Port Harcourt — Verified Listings | HonestCars', 'SUVs under ₦15 million in Port Harcourt — RAV4, CR-V, Sportage, X-Trail and more, with mileage, documents and verification grades.', '{"body_type":"suv","max_price_kobo":1500000000}', '/cars/suv-under-15m', 1, 40),
  ('suv-under-25m', 'body_budget', NULL, 'SUVs under ₦25m in Port Harcourt', 'SUVs under ₦25m in Port Harcourt', 'This is the sweet spot for a PH family: newer RAV4, Highlander and Santa Fe money. Compare the certified ones first — the inspection report tells you what the photos will not.', 'SUVs Under ₦25m in Port Harcourt — Verified Stock | HonestCars', 'SUVs under ₦25 million in Port Harcourt with verified mileage, inspection grades and honest condition notes.', '{"body_type":"suv","max_price_kobo":2500000000}', '/cars/suv-under-25m', 1, 41),
  ('sedan-under-10m', 'body_budget', NULL, 'Sedans under ₦10m in Port Harcourt', 'Sedans under ₦10m in Port Harcourt', 'Clean, sensible saloon cars under ₦10m — mostly Camry, Corolla, Elantra and Altima. Good for a first car, better for a daily commute through Rumuokoro.', 'Sedans Under ₦10m in Port Harcourt — Verified Listings | HonestCars', 'Sedans under ₦10 million in Port Harcourt — Camry, Corolla, Elantra, Altima. Honest prices, grades and mileage.', '{"body_type":"sedan","max_price_kobo":1000000000}', '/cars/sedan-under-10m', 1, 42),
  ('certified', 'tag', NULL, 'HonestCars-Certified cars in Port Harcourt', 'HonestCars-Certified cars in Port Harcourt', 'These are the cars our inspectors have scanned, driven and photographed themselves — with an honest condition note on each listing that names the faults instead of hiding them.', 'HonestCars-Certified Cars in Port Harcourt — Full Inspection | HonestCars', 'Every HonestCars-Certified car in Port Harcourt: OBD2 scan, documents sighted, road test, honest condition note. Browse the fully inspected stock.', '{"grade":"certified"}', '/cars/certified', 1, 50);
INSERT INTO services (`slug`, `name`, `promise`, `icon`, `from_price_kobo`, `cta_label`, `position`, `is_active`) VALUES
  ('inspection', 'Pre-Purchase Inspection', 'An inspector stands next to the car, scans it and tells you the truth before you pay.', 'search-check', 2500000, 'Book inspection', 10, 1),
  ('concierge', 'Find-My-Car Concierge', 'Tell us the brief once. We bring up to 3 verified, inspected options in 48–72 hours.', 'compass', 5000000, 'Start my search', 20, 1),
  ('documents', 'Customs & Document Services', 'Customs verification, registration, licence renewal, tinted permit and insurance — handled.', 'file-check', 3000000, 'Request service', 30, 1),
  ('sell-swap', 'Sell or Swap Your Car', 'Free valuation within 24 hours from live network data, then we sell or swap it.', 'repeat', NULL, 'Get valuation', 40, 1),
  ('tracking', 'Car Tracking & Security', 'Standard, Premium and Fleet tracker bundles installed in Port Harcourt, with renewal handled.', 'shield', 4500000, 'See bundles', 50, 1),
  ('hire', 'Car Hire', 'Daily, weekly and corporate hire with or without a driver — airport pickup available.', 'car', NULL, 'Request quote', 60, 1),
  ('research', 'Research & Reports', 'TCO reports, auction sourcing analysis and market price checks, delivered in 48–72 hours.', 'bar-chart', 3500000, 'Order a report', 70, 1),
  ('consultation', 'Paid Consultation', '30 minutes with someone who buys cars in Port Harcourt for a living. Bring your shortlist.', 'video', 1000000, 'Book 30 minutes', 80, 1),
  ('parts', 'Spare-Parts Sourcing', 'VIN-matched parts sourced with escrow-protected milestone payment — not guesswork.', 'package', NULL, 'Request a part', 90, 1),
  ('dealer-services', 'B2B: Dealer Services', 'Media shoots, featured placement and market intelligence for lots in Port Harcourt.', 'store', NULL, 'See packages', 100, 1);
INSERT INTO testimonials (`customer_name`, `area`, `quote`, `service_tag`, `rating`, `position`, `is_published`) VALUES
  ('Chidi O.', 'Woji', 'They told me the Camry I liked had a resprayed boot lid before I paid for the inspection. No other lot would have said that. I bought it anyway, with my eyes open.', 'inspection', 5, 1, 1),
  ('Mrs. Amadi', 'GRA Phase 2', 'I sent my brief on WhatsApp at night and had three inspected options by Thursday. The swap was handled end to end — I only showed up to sign.', 'concierge', 5, 2, 1),
  ('Emeka N.', 'Rumuokoro', 'The tracker was installed in my compound and the renewal reminder came before I even thought about it. Small thing, but it means they are watching.', 'tracking', 5, 3, 1),
  ('Tunde A.', 'Trans-Amadi', 'Documents were the part I dreaded. Customs verification and registration were done in nine days and I got updates without chasing anybody.', 'documents', 5, 4, 1),
  ('Ngozi I.', 'Peter Odili Road', 'I have bought two cars through HonestCars. The second one they talked me out of a bad buy and into a better one. That is why I came back.', 'sell-swap', 5, 5, 1),
  ('Fleet officer, oil & gas firm', 'Port Harcourt', 'We needed four hire vehicles for a two-week rotation with proper invoices. Quote, paperwork and tracking proposals all arrived in one day.', 'hire', 5, 6, 1);
INSERT INTO blog_posts (`slug`, `title`, `category`, `excerpt`, `hero_image`, `hero_alt`, `author_name`, `author_role`, `read_minutes`, `status`, `published_at`, `is_featured`, `make_tags`) VALUES
  ('2015-toyota-camry-honest-buyers-guide', 'The 2015 Toyota Camry: what ₦12m actually buys in Port Harcourt', 'honest_buyers_guide', 'We put a 2015 Camry through the full checklist and wrote down everything — the good, the tired and the priced-in.', '/img/seed/og-default.svg', '2015 Toyota Camry inspection in Port Harcourt', 'Raph Nicks', 'Head of Inspections', 9, 'published', '2026-09-28 00:00:00', 1, '["Toyota"]'),
  ('tokunbo-vs-nigerian-used-ph', 'Tokunbo vs Nigerian-used: the honest maths for Port Harcourt buyers', 'market_intel', 'A cheaper import is not always cheaper. Here is the running-cost maths we run for buyers before they commit.', '/img/seed/og-default.svg', 'Comparing tokunbo and Nigerian-used cars in Port Harcourt', 'Ada George', 'Market Analyst', 7, 'published', '2026-09-24 00:00:00', 0, '["Toyota","Honda"]'),
  ('odometer-fraud-check-yourself', 'How to check an odometer yourself before you pay a deposit', 'honest_buyers_guide', 'Seven checks anyone can do in ten minutes, plus the two tricks dealers use to reset a mileage that still fool buyers.', '/img/seed/og-default.svg', 'Odometer close-up during a HonestCars inspection', 'Raph Nicks', 'Head of Inspections', 6, 'published', '2026-09-20 00:00:00', 0, '["Toyota"]'),
  ('customs-papers-explained', 'Customs papers, explained without the jargon', 'ownership_maintenance', 'What "duty sighted" really means, what happens if papers are missing, and how to verify them yourself.', '/img/seed/og-default.svg', 'Verifying customs documents for a car in Port Harcourt', 'Chinelo U.', 'Documentation Lead', 8, 'published', '2026-09-16 00:00:00', 0, '["Toyota"]'),
  ('ph-fuel-cost-by-model', 'What 100km really costs in PH traffic, by model', 'market_intel', 'We tracked real consumption on Camry, Corolla, CR-V, RX 350 and Hilux over the same Aba Road run.', '/img/seed/og-default.svg', 'Fuel economy comparison chart for Port Harcourt cars', 'Ada George', 'Market Analyst', 5, 'published', '2026-09-12 00:00:00', 0, '["Toyota","Honda"]'),
  ('tyres-you-should-walk-away-from', 'Three tyre conditions that should end your inspection', 'honest_buyers_guide', 'Uneven wear tells you more about a car than the dealer ever will. What to look for and what it costs to fix.', '/img/seed/og-default.svg', 'Tyres and tread depth check on a used car', 'Raph Nicks', 'Head of Inspections', 4, 'published', '2026-09-08 00:00:00', 0, '["Toyota"]');
INSERT INTO faqs (`scope`, `question`, `answer`, `position`, `is_active`) VALUES
  ('global', 'What do the three verification grades mean?', 'Network-Listed means the dealer gave us the data but we have not seen the car. Field-Checked means an inspector physically stood next to it and photographed it. HonestCars-Certified means it passed our full checklist — OBD2 scan, documents sighted, road test and an honest condition note you can read on the listing.', 1, 1),
  ('global', 'Do I pay the seller directly?', 'No. All payments for a car we are handling go through HonestCars-protected channels. If someone asks you to pay a seller or a "third party" directly, it is not us — stop and message our WhatsApp.', 2, 1),
  ('global', 'Can I bring my own mechanic?', 'Yes, always. We would rather you did. We only ask that you book the viewing so the dealer opens the car for you and nothing is hidden between visits.', 3, 1),
  ('facet:suv-under-15m', 'Are these SUVs really under ₦15m?', 'Every car on this page is listed below ₦15,000,000. Prices move — we refresh the page as dealers update stock, and we will tell you if a price changes before you travel.', 1, 1),
  ('facet:suv-under-15m', 'Will an older SUV cost me more in fuel and parts?', 'Usually yes on fuel, and it depends on the model for parts. The Camry and Corolla platforms are the cheapest to keep on the road in PH; among SUVs, older RAV4 and CR-V models have the best parts availability.', 2, 1),
  ('facet:toyota', 'Why are there so many Toyotas on HonestCars?', 'Because Port Harcourt buys them — parts are everywhere, mechanics know them, and resale value holds. We list whatever is genuinely good stock, and Toyota tends to pass our checklist more often.', 1, 1),
  ('facet:toyota', 'Tokunbo or Nigerian-used Toyota?', 'Both, and we label each one. A Nigerian-used car with a verifiable service history can be better value than a low-grade import. Ask us and we will give you the honest comparison on the specific cars you are looking at.', 2, 1);
